use crate::pathfinding::{Field, Grid, Pool};
use crate::rules::{Refusal, REFUSAL_KINDS};
use crate::*;

const MAGIC: &[u8; 4] = b"OSSV";
const STATE_VERSION: u16 = 63;

const REFUSALS: [Refusal; REFUSAL_KINDS] = [
    Refusal::Unset,
    Refusal::NoSlot,
    Refusal::Cooldown,
    Refusal::Energy,
    Refusal::NoTarget,
    Refusal::UnseenTarget,
    Refusal::TargetFilter,
    Refusal::NoSpawnSlot,
