pub fn spawn_group_boss_window(_image: &[u8]) -> Result<(), String> {
    let mut host = pack_run::start()?;
    pack_run::advance(&mut host, 2)?;
    let boss = (0..MAX_UNITS)
        .filter(|&u| {
