            }
            let (x, y) = s.position_fixed(k);
            let (x, y) = (i64::from(x), i64::from(y));
            let mut nearest = None;
            let mut best = i64::MAX;
            for (i, g) in geoms.iter().enumerate() {
                let dx = x - g.cx;
                let dy = y - g.cy;
                let d = dx * dx + dy * dy;
                if d < best {
                    best = d;
                    nearest = Some(i);
                }
            }
            nearest == Some(index)
        })
