    const r2=rel?rel+'/'+e.name:e.name;
    if(e.isDirectory()){
      if(e.name==='vendor'||e.name==='node_modules'||e.name==='three'){ out.push({dir:r2, skipped:true}); continue; }
      walk(p,r2);
    } else if(e.name.endsWith('.js')||e.name.endsWith('.mjs')){
      const txt=fs.readFileSync(p,'utf8');
      const lines=txt.split(/\r?\n/);
      let c=0, block=0;
      const starts=[];
      for(let i=0;i<lines.length;i++){
        const s=lines[i].trim();
        if(s.startsWith('//')) { c++; starts.push(i+1); }
        else if(s.startsWith('/*')) { block++; starts.push(i+1); }
      }
      out.push({file:'js/client/'+r2, lines:lines.length, slash:c, blockStart:block, first:starts.slice(0,400)});
    }
  }
}
walk(root,'');
