  if (!held) return 'RELEASED after '+((Date.now()-t0)/1000).toFixed(0)+'s';
  // check holder liveness: no dispatch in last 4 min
  try {
    const lines = fs.readFileSync('/workspace/oscraft/.gm/exec-spool/.dispatch-ledger.json','utf8').split('\n').filter(Boolean);
    const mine = lines.filter(l=>l.includes('drain-icons-688g-art-r2'));
    const lastTs = mine.length ? JSON.parse(mine[mine.length-1]).ts : 0;
    if (Date.now()-lastTs > 4*60*1000) return 'STALE_HOLDER last dispatch '+((Date.now()-lastTs)/1000).toFixed(0)+'s ago';
  } catch(e){}
  try { fs.appendFileSync('/dev/null','') } catch(e){}
  const end = Date.now()+20000; while(Date.now()<end){}
}
return 'TIMEOUT still held';

