  left: "ui-left",
  hud: "hud",
  win: "win",
  right: "ui-right",
  "bar-left": "ui-bar-left",
  "bar-mid": "ui-bar-mid",
};
const HIDE_WHEN_EMPTY = new Set(["win"]);

const STYLE = `
.w-overlay{position:fixed;z-index:2;pointer-events:none;color:var(--text);font:var(--t-label)/1.25 var(--font)}
.w-overlay>.w-root{pointer-events:auto}
