    text: &dyn Fn(&str) -> Result<String, String>,
) -> Result<Effect, String> {
    let code = effect_kind(kind).ok_or_else(|| format!("unknown_effect: {kind} (known: {})", sim::MOD_EFFECTS.join(", ")))?;
    let (p0, p1, p2) = match kind {
